"""
Generate an MCP server whose tools mirror the operations described by a
minimal OpenAPI 3.0 specification, using fastmcp's OpenAPI integration.
"""

import asyncio

import httpx
from fastmcp import FastMCP


def build_mcp_server(
    openapi_spec: dict,
    client: httpx.AsyncClient,
    name: str = "OpenAPI MCP Server",
) -> FastMCP:
    """Build a FastMCP server whose tools mirror an OpenAPI spec's operations.

    Args:
        openapi_spec: A minimal OpenAPI 3.0 specification as a Python dict.
        client: An httpx.AsyncClient already configured with the API base URL.
        name: Display name for the generated MCP server.

    Returns:
        A FastMCP server instance with generated tools/resources.
    """
    return FastMCP.from_openapi(
        openapi_spec=openapi_spec,
        client=client,
        name=name,
    )


# --- Example wiring -----------------------------------------------------

EXAMPLE_OPENAPI_SPEC: dict = {
    "openapi": "3.0.0",
    "info": {"title": "Pet Store API", "version": "1.0.0"},
    "paths": {
        "/pets": {
            "get": {
                "operationId": "listPets",
                "summary": "List all pets",
                "responses": {"200": {"description": "A list of pets"}},
            },
            "post": {
                "operationId": "createPet",
                "summary": "Create a pet",
                "requestBody": {
                    "required": True,
                    "content": {
                        "application/json": {
                            "schema": {
                                "type": "object",
                                "properties": {
                                    "name": {"type": "string"},
                                    "tag": {"type": "string"},
                                },
                                "required": ["name"],
                            }
                        }
                    },
                },
                "responses": {"201": {"description": "Pet created"}},
            },
        },
        "/pets/{petId}": {
            "get": {
                "operationId": "getPetById",
                "summary": "Get a pet by id",
                "parameters": [
                    {
                        "name": "petId",
                        "in": "path",
                        "required": True,
                        "schema": {"type": "integer"},
                    }
                ],
                "responses": {"200": {"description": "A single pet"}},
            }
        },
    },
}


def main() -> None:
    client = httpx.AsyncClient(base_url="https://api.example.com")
    mcp = build_mcp_server(EXAMPLE_OPENAPI_SPEC, client, name="Pet Store MCP Server")
    mcp.run()


if __name__ == "__main__":
    main()

